{"path": "src/index.js", "content": "require('dotenv').config();
const express = require('express');
const pino = require('pino');
const { addEvents } = require('./ingest');
const { getDb } = require('./db');

const log = pino();
const app = express();
app.use(express.json({ limit: '1mb' }));

app.get('/health', async (req, res) => {
  res.json({ status: 'ok' });
});

app.post('/events', async (req, res) => {
  const body = req.body;
  if (!body) return res.status(400).json({ error: 'empty body' });
  try {
    addEvents(body);
    res.status(202).json({ accepted: Array.isArray(body) ? body.length : 1 });
  } catch (err) {
    log.error({ err }, 'Failed to accept events');
    res.status(500).json({ error: 'failed to accept events' });
  }
});

const port = process.env.PORT || 3000;

// ensure indexes on startup
(async function main() {
  try {
    const db = await getDb();
    await db.collection('events').createIndex({ customerId: 1, eventId: 1 }, { unique: true, name: 'customer_event_unique' });
    log.info('Index ensured on startup');
  } catch (err) {
    log.error({ err }, 'Error ensuring index');
    process.exit(1);
  }

  app.listen(port, () => {
    log.info({ port }, 'Event ingestion service started');
  });
})();
"}

{"path": "src/watch.js", "content": "require('dotenv').config();
const pino = require('pino');
const { getDb } = require('./db');

const log = pino();

async function runWatcher() {
  const db = await getDb();
  const coll = db.collection('events');

  log.info('Starting change stream watcher on events collection...');

  const changeStream = coll.watch([], { fullDocument: 'updateLookup' });

  changeStream.on('change', change => {
    try {
      log.info({ change }, 'Change stream event');
      // Simulate downstream profile update job trigger
      if (change.operationType === 'insert' || change.operationType === 'update') {
        const doc = change.fullDocument;
        // lightweight simulated job enqueue
        log.info({ customerId: doc.customerId, eventType: doc.eventType }, 'Enqueued profile-update job');
      }
    } catch (err) {
      log.error({ err }, 'Error handling change event');
    }
  });

  changeStream.on('error', err => {
    log.error({ err }, 'Change stream error');
    process.exit(1);
  });
}

runWatcher().catch(err => {
  log.error({ err }, 'Watcher failed to start');
  process.exit(1);
});
"}

{"path": "scripts/seed.js", "content": "require('dotenv').config();
const pino = require('pino');
const { getDb } = require('../src/db');

const log = pino();

async function seed() {
  const db = await getDb();
  const coll = db.collection('events');

  const sampleCustomers = ['alice', 'bob', 'carol', 'dan'];
  const ops = [];
  for (let i = 0; i < 200; i++) {
    const customerId = sampleCustomers[i % sampleCustomers.length];
    const eventId = `evt-${Math.floor(i/2)}`; // create duplicates on purpose
    const doc = {
      customerId,
      eventId,
      eventType: ['page_view', 'click', 'purchase'][i % 3],
      timestamp: new Date(),
      payload: { idx: i }
    };
    // upsert to keep idempotent seed
    ops.push({ updateOne: { filter: { customerId: doc.customerId, eventId: doc.eventId }, update: { $set: doc }, upsert: true } });
  }

  log.info({ count: ops.length }, 'Seeding events with upsert bulk ops (idempotent)');
  const res = await coll.bulkWrite(ops, { ordered: false });
  log.info({ result: res.result }, 'Seed complete');
}

seed().then(() => process.exit(0)).catch(err => { console.error(err); process.exit(1); });
"}

